package com.writablebookwiki.core.document;

import static org.junit.jupiter.api.Assertions.*;
import java.util.Base64;
import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;

/** Captured using the unmodified release 0.1.1 JAR, not regenerated by the codec under test. */
class ReleaseCompatibilityTest {
    @Test void retainsReleaseBytesAndContentIdentityAcrossEveryCurrentBlockKind() throws Exception {
        byte[] bytes;
        try (var input = getClass().getResourceAsStream("/compatibility/release-0.1.1.ewd.base64")) {
            assertNotNull(input);
            bytes = Base64.getDecoder().decode(new String(input.readAllBytes(), StandardCharsets.US_ASCII).trim());
        }
        var codec = new WikiDocumentCodec();
        WikiDocument document = codec.decode(bytes);
        assertEquals("兼容样本", document.title());
        assertEquals(21, document.blocks().size());
        assertEquals("4f473c178c66d2af41d1660d664e5e92252d49b6aa897e640b75fd5253934eb3", codec.contentHash(document));
        assertArrayEquals(bytes, codec.encode(document));
        var editor = new WikiDocumentEditor(document);
        assertTrue(editor.replaceTitle("changed"));
        assertTrue(editor.undo());
        assertArrayEquals(bytes, codec.encode(editor.document()));
    }
}
